import sys
lines = sys.stdin.read().splitlines()
out = []
if lines:
    parts = lines[0].split()
    n, m = int(parts[0]), int(parts[1])
    nums = [int(x) for x in lines[1].split()]
    bit = [0] * (n + 1)
    def add(idx, delta):
        while idx <= n:
            bit[idx] += delta
            idx += idx & (-idx)
    def query(idx):
        s = 0
        while idx > 0:
            s += bit[idx]
            idx -= idx & (-idx)
        return s
    for i, x in enumerate(nums, 1): add(i, x)
    for line in lines[2:2+m]:
        cmd = line.split()
        if not cmd: continue
        if cmd[0] == 'UPDATE':
            idx, delta = int(cmd[1]), int(cmd[2])
            add(idx, delta)
        elif cmd[0] == 'QUERY':
            l, r = int(cmd[1]), int(cmd[2])
            out.append(str(query(r) - query(l - 1)))
print(' '.join(out))
